SELECT MAX(m.reporting_year || '-' || LPAD(m.period_value::text, 2, '0'))
FROM esg_metric_data m
WHERE m.company_id = #{companyId}
  AND m.reporting_year = #{year}
  AND m.status = 'APPROVED'
  AND m.period_value = #{month}
  AND m.facility_id = #{facilityId}

SELECT MAX(m.reporting_year || '-' || LPAD(m.period_value::text, 2, '0'))
FROM esg_metric_data m
WHERE m.company_id = #{companyId}
  AND m.reporting_year = #{year}
  AND m.facility_id = #{facilityId}

SELECT MAX(m.reporting_year || '-' || LPAD(m.period_value::text, 2, '0'))
FROM esg_metric_data m
WHERE m.company_id = #{companyId}
  AND m.reporting_year = #{year}
  AND m.status IN ('DRAFT', 'PENDING', 'REJECTED')
  AND m.facility_id = #{facilityId}

SELECT COUNT(*)
FROM esg_metric_data
WHERE company_id = #{companyId}
  AND status = 'PENDING'
  AND facility_id = #{facilityId}

SELECT evaluation_name FROM esg_evaluation_configs
WHERE company_id = #{companyId} AND reporting_year = #{year}
ORDER BY id DESC LIMIT 1

SELECT evaluation_version FROM esg_evaluation_configs
WHERE company_id = #{companyId} AND reporting_year = #{year}
ORDER BY id DESC LIMIT 1

SELECT disclaimer FROM esg_evaluation_configs
WHERE company_id = #{companyId} AND reporting_year = #{year}
ORDER BY id DESC LIMIT 1
